      }

      link.prevDep = activeSub.depsTail
      link.nextDep = undefined
      activeSub.depsTail!.nextDep = link
      activeSub.depsTail = link

      if (activeSub.deps === link) {
        activeSub.deps = next
      }
    }
  }

  if (__DEV__ && activeSub.onTrack) {
    activeSub.onTrack(
      extend(
        {
          effect: activeSub,
        },
        debugInfo,
      ),
    )
  }

  return link
}

notifyDependencySubscribers(dep: any, debugInfo?: any): void {
  this.runNotifyCoordination(dep, debugInfo)
  startBatch()
  try {
    if (__DEV__) {
      for (let head = dep.subsHead; head; head = head.nextSub) {
        if (
          __DEV__ &&
          head.sub.onTrigger &&
          !(head.sub.flags & EffectFlags.NOTIFIED)
        ) {
          head.sub.onTrigger(
            extend(
              {
                effect: head.sub,
              },
              debugInfo,
            ),
          )
        }
      }
    }
    for (let link = dep.subs; link; link = link.prevSub) {
      link.sub.notify()
    }
  } finally {
    endBatch()
  }
}

bumpDepAndNotify(
  dep: any,
  debugInfo: any,
  bumpEpoch: () => number,
): void {
  dep.version++
  const next = bumpEpoch()
  this.syncReactiveEpoch(next)
  this.notifyDependencySubscribers(dep, debugInfo)
}

trackReactiveProperty(
  target: object,
  type: any,
  key: unknown,
  targetMap: WeakMap<object, Map<any, any>>,
  createDep: () => any,
): void {
  this.runTrackCoordination(target, key)
  if (shouldTrack && activeSub) {
    let depsMap = targetMap.get(target)
    if (!depsMap) {
      targetMap.set(target, (depsMap = new Map()))
    }
    let dep = depsMap.get(key)
    if (!dep) {
      depsMap.set(key, (dep = createDep()))
    }
    if (__DEV__) {
      dep.track({
        target,
        type,
        key,
      })
    } else {
      dep.track()
    }
  }
}

